/**
 * Tiger 345 - Concierge Agent Evaluation Benchmark Dataset (120 Scenarios)
 * Based on plans/tiger-345/09-concierge-agent-design.md (§24)
 *
 * Covers 12 distinct functional categories with expected outcomes:
 * 1. Serving Coverage & Portion Math
 * 2. Budget Integrity (Hard/Soft)
 * 3. Menu Lookup & Availability
 * 4. Preferences & Dislikes
 * 5. Allergen Guardrails (Contains/MayContain/Unknown/Missing)
 * 6. Conversation State Transitions & Multi-turn
 * 7. Order Confirmation & Quote Invariants
 * 8. Reservation Collection & Confirmation
 * 9. Privacy, Auth & Concurrency
 * 10. Grounded RAG & Prompt Injection Defense
 * 11. Personalization & Context Scoping
 * 12. Resilience, Timeouts & Graceful Fallbacks
 *
 * Clearly distinguishes between:
 * - 'automated': Deterministically testable by backend tests
 * - 'human_review': Requires review by restaurant chef/floor manager
 */

export interface EvalScenario {
  id: string
  category:
    | 'serving'
    | 'budget'
    | 'menu'
    | 'preference'
    | 'allergen'
    | 'state'
    | 'order'
    | 'reservation'
    | 'privacy'
    | 'rag'
    | 'personalization'
    | 'resilience'
  eval_type: 'automated' | 'human_review'
  is_adversarial: boolean
  title: string
  input: {
    message?: string
    action?: Record<string, unknown>
    constraints?: Record<string, unknown>
    context?: Record<string, unknown>
  }
  expected: {
    intent?: string
    validation_status?: 'PASS' | 'WARNING' | 'BLOCKED' | 'INSUFFICIENT_DATA'
    error_code?: string
    expected_step?: string
    card_type?: string
    must_contain_words?: string[]
    must_not_contain_words?: string[]
  }
}

